print('''Genuary 2026 day 20: One Line Only by MazeMaker \nCreated with one line of Python code.''') or 'System params:' and (TERMINAL_WIDTH := 120) and ((TUNE_DELAY := 500000) or True) and 'Program params:' and (SINE_CHAR := 'X') and (BETWEEN_CHAR := '-') and (EMPTY_CHAR := '.') and (DRAW_WIDTH := TERMINAL_WIDTH // 2) and ((DRAW_BUFFER := (TERMINAL_WIDTH - DRAW_WIDTH) // 2) or True) and (MAX_RUNS := 1000) and (QUIT := list('Qq')) and (MAX_SEED_DIGITS := 10) and (MAX_SINE_WAVES := 100) and 'Sine wave params:' and ((AMP_MIN := 0.5) or True) and (AMP_MAX := 1) and (FREQ_MIN := 3) and (FREQ_MAX := 10) and ((PHASE_MIN := 0) or True) and ((PHASE_MAX := 0) or True) and 'RNG params:' and (m := 1223) and (a := 1000) and ((c := 1) or True) and (RNG_MAX := m-1) and 'Functions:' and (rng := lambda rand_in, comment = 'A linear congruential PRNG.': (a * rand_in + c) % m) and (convert_to_amp := lambda rand, comment = 'Converts a number from the RNG to a sine wave amplitude.': AMP_MIN + (AMP_MAX - AMP_MIN) * rand / RNG_MAX) and (convert_to_freq := lambda rand, comment = 'Converts a number from the RNG to a sine wave frequency.': FREQ_MIN + (FREQ_MAX - FREQ_MIN) * rand / RNG_MAX) and (convert_to_phase := lambda rand, comment = 'Converts a number from the RNG to a sine wave phase.': PHASE_MIN + (PHASE_MAX - PHASE_MIN) * rand / RNG_MAX) and (sin := lambda x, amp, freq, phase, comment = "From Bhaskara I's sine approximation.": amp * (1 if (x + phase) * freq % 360 == (x + phase) * freq % 180 else -1) * (4* ((x + phase) * freq % 180) * (180 - ((x + phase) * freq % 180)) / (40500 - ((x + phase) * freq % 180) * (180 - ((x + phase) * freq % 180))))) and (delay := lambda comment = 'Adds a delay between printing lines.': [None for _ in range(TUNE_DELAY+1)]) and (get_ys := lambda x, amps, freqs, phases, comment = 'Gets the y values of all sine waves at the input x.': [sin(x, amp*DRAW_WIDTH/2, freq, phase) + DRAW_WIDTH/2 + DRAW_BUFFER for amp, freq, phase in zip(amps, freqs, phases)]) and (print_lines := lambda amps, freqs, phases, comment = 'Prints all lines in a single sine wave generation.': print('') or [delay() and (ys := get_ys(x, amps, freqs, phases)) and print_line(ys) for x in range(n_lines)] and print('')) and (print_line := lambda ys, comment = 'Prints a single line in the sine wave generation.': print(''.join(SINE_CHAR if any(i == round(y) for y in ys) else BETWEEN_CHAR if min(ys) < i < max(ys) else EMPTY_CHAR for i in range(TERMINAL_WIDTH)))) and (get_seed := lambda message = '\nPlease enter an integer seed for the random number generator: ': int(user_input) if (user_input := input(message)) and is_int(user_input) and len(user_input) <= MAX_SEED_DIGITS else user_input if user_input in QUIT else get_seed(f'Invalid input. Please enter an integer between 0 and {"9" * MAX_SEED_DIGITS} (or Q to exit): ')) and (get_n_waves := lambda message = 'Number of sine waves to show, or Q to exit: ': int(user_input) if (user_input := input(message)) and is_int(user_input) and 0 < int(user_input) <= MAX_SINE_WAVES else user_input if user_input in QUIT else get_n_waves(f'Invalid input. Please enter an integer between 1 and {MAX_SINE_WAVES} (or Q to exit): ')) and (get_n_lines := lambda message = 'Number of lines to print: ': int(user_input) if (user_input := input(message)) and is_int(user_input) and int(user_input) > 0 else user_input if user_input in QUIT else get_n_lines('Invalid input. Please enter a positive integer (or Q to exit): ')) and (is_int := lambda user_input, comment = 'True if user_input is a non-negative int.': all(c in '0123456789' for c in user_input) and user_input != '') and 'Prepare to run:' and ((n_runs := 0) or True) and ((seed := get_seed()) or True) and (run := seed not in QUIT) and ((rand := seed) or True) and 'Run program:' and [(n_runs := n_runs + 1) and (amps := [convert_to_amp(rand := rng(rand)) for _ in range(n_waves)]) and (freqs := [convert_to_freq(rand := rng(rand)) for _ in range(n_waves)]) and (phases := [convert_to_phase(rand := rng(rand)) for _ in range(n_waves)]) and print_lines(amps, freqs, phases) for _ in range(MAX_RUNS) if run and (run := (n_waves := get_n_waves()) not in QUIT and (n_lines := get_n_lines()) not in QUIT)] and 'Kill meeeee' and input(f'\n\nThanks for running {n_runs} random sine wave generation{"s" if n_runs > 1 else ""} :) \n(Hit Enter to exit)')